package com.kewu.app.ui

/**
 * 全国高等学校名单（教育部 2025-06-20 发布，经 GitHub lzy201314/Universities2025 转换的 JSON 生成），
 * 共收录普通高等学校 2919 所（本科 + 高职专科，不含成人高校），另含名单外补充项（港澳台等）23 条。
 *
 * 字段：
 * - [name] 学校全称（展示项）
 * - [py] 全拼小写无空格（"qinghuadaxue"），支持拼音模糊搜
 * - [abbr] 拼音首字母简写（"qhdx"），支持首字母模糊搜
 * - [province] 所在省市（教育部名单的所在地字段，城市级）
 *
 * 本文件由脚本离线生成（数据源：中华人民共和国教育部《全国高等学校名单》，截至 2025-06-20），
 * 更新方式：下载最新名单 JSON → 重新跑生成脚本；勿手改单条数据。
 */

data class University(val name: String, val py: String, val abbr: String, val province: String)

private fun u(name: String, py: String, abbr: String, province: String) = University(name, py, abbr, province)

/** 模糊匹配：命中 名称 / 全拼 / 简写（子串），大小写不敏感。 */
fun University.matches(query: String): Boolean {
    val q = query.trim().lowercase()
    if (q.isEmpty()) return true
    return name.contains(q, ignoreCase = true) || (py.isNotEmpty() && py.contains(q)) || (abbr.isNotEmpty() && abbr.contains(q))
}

/**
 * 全国高校列表（按所在地分组，组内按教育部名单原序）。
 *
 * ★ 2026-10-26 兼容性修复（队友 vivo 点「选择学校」即闪退，小米正常）：原来 2900+ 条数据全写在
 * 一个 `listOf(...)` 里，编译成单个 5 万码元的静态初始化方法，首次点开选择器时在主线程整段执行；
 * 超大方法在不同厂商 ART（编译/校验/解释器）上的行为不一致。现拆成每段 200 条的小函数，
 * 首次访问才拼装（by lazy，线程安全），并由注册页在后台线程预热、搜索也放后台算。
 * 重新生成数据时请保持「分段函数」结构，勿再合并成一个大 listOf。
 */
val ALL_UNIVERSITIES: List<University> by lazy {
    ArrayList<University>(2942).apply {
        addAll(uniPart0())
        addAll(uniPart1())
        addAll(uniPart2())
        addAll(uniPart3())
        addAll(uniPart4())
        addAll(uniPart5())
        addAll(uniPart6())
        addAll(uniPart7())
        addAll(uniPart8())
        addAll(uniPart9())
        addAll(uniPart10())
        addAll(uniPart11())
        addAll(uniPart12())
        addAll(uniPart13())
        addAll(uniPart14())
    }
}

