/** 本校（开发团队所属）—— 学校选择器里固定置顶，方便本校同学一眼选中。 */
private const val HOME_SCHOOL = "重庆对外经贸学院"

/** 按查询串过滤（名称 / 全拼 / 简写），供注册页学校选择器调用。 */
fun searchUniversities(query: String): List<University> {
    val list = ALL_UNIVERSITIES.filter { it.matches(query) }
    // ★ 本校固定排第一位（sortedBy 是稳定排序，其余学校保持原顺序不变）
    return list.sortedBy { if (it.name == HOME_SCHOOL) 0 else 1 }
}
